<script setup>
import { ref, computed, onMounted, watch } from 'vue';
import { request } from '../../api/http';
import { session } from '../../lib/session';
import { ccCore } from '../../api/cc-core';
import { parseLeadCsv, milestoneNames } from '../../lib/cc-journey';
import { workbook } from '../../lib/xlsx';
import { downloadCsv } from '../../lib/cc';
const emit=defineEmits(['changed']);
const schedulerStatus=ref(null);
async function checkScheduler(){await run(async()=>{schedulerStatus.value=(await request('life_slimming.api.cc_scheduler_status.run',{args:{},csrfToken:session.csrf_token})).message;});}
const moveStep=ref(1),ruleReview=ref(null),pasteText=ref(''),checks=ref(null),capacityAccepted=ref(false),capacityWarning=ref([]),checking=ref(false);
function downloadWorkbook(filename,sheets){const url=URL.createObjectURL(workbook(sheets));const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function template(){downloadWorkbook('cc-lead-template.xlsx',[{name:'Leads',rows:[['name','mobile','source','branch','alt','city','interest','notes','agent']]}]);}
function readPaste(){try{const text=pasteText.value.trim();bulk.value=parseLeadCsv(text.includes('\t')?text.split('\n').map(line=>line.split('\t').map(v=>'"'+v.replaceAll('"','""')+'"').join(',')).join('\n'):text);checks.value=null;error.value='';}catch(e){error.value=e.message;}}
function reviewRule(){if(!rule.value.rule_name.trim()){error.value='Give the rule a name.';return;}ruleReview.value=JSON.parse(JSON.stringify(rule.value));error.value='';}

const tabs=['Move Leads','Auto Rules','Agents & Priority','Bulk Upload','Permissions'];
const tab=ref(0),busy=ref(false),error=ref(''),notice=ref(''),perm=ref(null),agents=ref([]),settings=ref({}),rules=ref([]),rank=ref([]),items=ref([]),selected=ref([]),lastBatch=ref(''),conflicts=ref([]),force=ref('');
const filter=ref({owners:[],stages:[],sub_statuses:[],sources:[],appt_statuses:[],milestones:[],last_results:[],overdue_only:false,dormant:false,from_date:'',to_date:''});
const toAgents=ref([]),method=ref('equal'),clearFollowup=ref(false),note=ref('');
const methods={equal:'Round robin',conversion:'Best conversion',bookings:'Most bookings',walkins:'Best walk-ins',smart:'Lowest load',free_leads:'Fewest leads in hand',free_fu:'Fewest follow-ups due'};
const bulk=ref([]),bulkResults=ref(null),bulkMode=ref('auto'),allowDup=ref(false),bulkMeta=ref({branches:[],sources:[]}),allowedUsers=ref('');
const rule=ref(newRule());
watch(rule,()=>ruleReview.value=null,{deep:true});
watch([bulk,bulkMode,toAgents,allowDup],()=>{checks.value=null;capacityAccepted.value=false;capacityWarning.value=[];},{deep:true});
const overloaded=computed(()=>[...new Set([...capacityWarning.value,...toAgents.value.filter(id=>agents.value.find(a=>a.agent===id)?.over_cap)])]);
function newRule(){return {rule_name:'',rule_type:'Time-over New Lead',enabled:1,test_mode:1,time_value:60,time_unit:'Minutes',max_shuffles:2,days:'Mon,Tue,Wed,Thu,Fri,Sat',from_time:'09:00:00',to_time:'19:00:00',every_minutes:5,absent_mode:'Auto',statuses:[],from_agents:[],sources:[],to_agents:[],method:'Round Robin',per_agent_limit:50};}
const ruleTypes=['Time-over New Lead','Time-over Follow-up','Absent Agent','Hot Lead Overdue','Visited Not Booked'];
const statuses=['Lead','No Response','Not Reachable','Switch OFF','TNA','Call Disconnected','Callback: Scheduled','Call & Confirm','Price Negotiation','Very Positive','Get Back','Out Station','Appointment Booked','Appointment no response','Walked In: Not Booked','Walked In & Booked','Existing Client'];
const distributionRules=computed(()=>rules.value.filter(r=>ruleTypes.includes(r.rule_type)));
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function load(){await run(async()=>{const p=await ccCore('perm');perm.value=p;if(!p.can_move)return;const [a,r,m]=await Promise.all([ccCore('agents'),ccCore('rules'),ccCore('bulk_meta')]);agents.value=a.agents;settings.value=a.settings;rules.value=r.rules;bulkMeta.value=m;allowedUsers.value=p.movers.join('\n');});}
onMounted(load);
function list(value){if(Array.isArray(value))return value;try{return JSON.parse(value||'[]');}catch{return String(value||'').split(',').map(v=>v.trim()).filter(Boolean);}}
function editRule(value){rule.value={...newRule(),...value};for(const key of ['statuses','from_agents','sources','to_agents'])rule.value[key]=list(value[key]);conflicts.value=[];}
async function preview(){await run(async()=>{const args=Object.fromEntries(Object.entries(filter.value).map(([k,v])=>[k,Array.isArray(v)?JSON.stringify(v):typeof v==='boolean'?+v:v]));const result=await ccCore('dist_preview',{...args,limit:300});items.value=result.items;selected.value=result.items.map(i=>i.lead);notice.value=result.count+' eligible leads. Review the list before moving.';moveStep.value=2;});}
async function move(){await run(async()=>{if(!selected.value.length||!toAgents.value.length)throw new Error('Select leads and receiving agents.');const data=await ccCore('dist_move',{leads:JSON.stringify(selected.value),to_agents:JSON.stringify(toAgents.value),method:method.value,clear_followup:+clearFollowup.value,note:note.value,accept_capacity:+capacityAccepted.value});if(data.capacity_warning){capacityWarning.value=data.capacity_warning;return;}lastBatch.value=data.batch;moveStep.value=1;notice.value=data.count+' leads moved.';items.value=[];selected.value=[];emit('changed');});}
async function undo(){await run(async()=>{const result=await ccCore('dist_undo',{batch:lastBatch.value});notice.value=result.undone+' leads moved back.';lastBatch.value='';emit('changed');});}
async function saveRule(){await run(async()=>{if(!rule.value.rule_name.trim())throw new Error('Give the rule a name.');const result=await ccCore('rule_save',{rule:JSON.stringify(ruleReview.value||rule.value),force:force.value});conflicts.value=result.conflict||[];if(result.saved){notice.value='Rule saved'+(rule.value.test_mode?' in test mode.':'.');rules.value=(await ccCore('rules')).rules;rule.value=newRule();ruleReview.value=null;force.value='';} });}
async function ranking(){await run(async()=>{rank.value=(await ccCore('rank',{agents:JSON.stringify(toAgents.value),method:method.value})).rows;});}
async function fileChanged(event){error.value='';bulkResults.value=null;const file=event.target.files?.[0];try{if(file?.size>2000000)throw new Error('Choose a file smaller than 2 MB.');if(file?.name.toLowerCase().endsWith('.xlsx')){busy.value=true;const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const response=await request('life_slimming.api.cc_bulk_upload.preview',{args:{content:btoa(binary)},csrfToken:session.csrf_token});bulk.value=response.message.rows;}else bulk.value=file?parseLeadCsv(await file.text()):[];}catch(e){error.value=e.message;bulk.value=[];}finally{busy.value=false;event.target.value='';}}
async function saveSettings(){await run(async()=>{settings.value=(await ccCore('settings_save',{settings:JSON.stringify(settings.value)})).settings;notice.value='Settings saved.';});}
async function preflight(){await run(async()=>{checks.value=await ccCore('bulk_check',{rows:JSON.stringify(bulk.value),mode:bulkMode.value,to_agents:JSON.stringify(toAgents.value),allow_dup:+allowDup.value});});}
async function upload(){await run(async()=>{if(!bulk.value.length)throw new Error('Choose a CSV file first.');if(['agent','split','rank'].includes(bulkMode.value)&&!toAgents.value.length)throw new Error('Choose receiving agents.');bulkResults.value=await ccCore('bulk_create',{rows:JSON.stringify(bulk.value),mode:bulkMode.value,to_agents:JSON.stringify(toAgents.value),method:method.value,allow_dup:+allowDup.value,accept_capacity:+capacityAccepted.value});if(bulkResults.value.capacity_warning){capacityWarning.value=bulkResults.value.capacity_warning;return;}if(bulkResults.value.validation_failed){checks.value=bulkResults.value;error.value='Resolve the invalid rows before creating leads.';return;}notice.value=bulkResults.value.created+' leads created.';bulk.value=[];emit('changed');});}
async function savePermissions(){await run(async()=>{const result=await ccCore('rule_save',{rule:JSON.stringify({rule_name:'Who can move leads',rule_type:'Permissions',enabled:1,test_mode:0,allowed_users:allowedUsers.value.split(/[\n,]/).map(s=>s.trim()).filter(Boolean)})});if(result.saved)notice.value='Permissions saved.';});}
function exportPreview(){downloadWorkbook('cc-distribution-preview.xlsx',[{name:'Leads',rows:[['Lead','Owner','Milestone','Next action'],...items.value.map(r=>[r.lead,r.owner,r.milestone,r.next_action])]}]);}
</script>
<template>
<section class="card cc-distribution"><header class="card-hdr">🔀 Lead Distribution <button class="btn btn-gy btn-sm" :disabled="busy" @click="load">Refresh</button></header>
<div class="card-body"><p v-if="error" role="alert" class="cc-error">{{error}}</p><p v-if="notice" role="status" class="cc-success">{{notice}}</p><p v-if="busy" role="status">Working…</p><p v-if="perm&&!perm.can_move">You do not have permission to distribute leads.</p>
<template v-if="perm?.can_move"><nav class="distribution-tabs" aria-label="Lead distribution"><button v-for="(label,i) in tabs" :key="label" class="btn btn-sm" :aria-pressed="tab===i" @click="tab=i">{{label}}</button></nav>
<nav v-if="tab===0" class="distribution-steps" aria-label="Move lead steps"><button v-for="(label,i) in ['1 · Filters','2 · Check list','3 · Agents and method']" :key="label" :disabled="i>0&&!items.length" :aria-current="moveStep===i+1?'step':undefined" @click="moveStep=i+1">{{label}}</button></nav><button v-if="lastBatch&&tab===0&&moveStep!==3" class="btn btn-gy" :disabled="busy" @click="undo">Undo last batch</button><div v-if="tab===0&&moveStep===1"><p>Preview eligible leads, choose receiving agents, then apply the move. Protected leads are excluded.</p><div class="distribution-fields"><label>Current owners<select v-model="filter.owners" multiple><option v-for="a in agents" :key="a.agent" :value="a.agent">{{a.name}}</option></select></label><label>Stages<select v-model="filter.stages" multiple><option v-for="s in ['UNTOUCHED','FOLLOW-UP','PIPELINE','SUCCESS','LOST','INVALID']" :key="s">{{s}}</option></select></label><label>Call outcomes<select v-model="filter.sub_statuses" multiple><option v-for="s in statuses" :key="s">{{s}}</option></select></label><label>Sources<select v-model="filter.sources" multiple><option v-for="s in bulkMeta.sources" :key="s">{{s}}</option></select></label><label>Milestones<select v-model="filter.milestones" multiple><option v-for="s in milestoneNames" :key="s">{{s}}</option></select></label><label>Appointments<select v-model="filter.appt_statuses" multiple><option v-for="s in ['Booked','Visited','Visited Booked','Visited Not Booked','Not Visited','Cancelled']" :key="s">{{s}}</option></select></label><label>Created from<input v-model="filter.from_date" type="date"></label><label>Created to<input v-model="filter.to_date" type="date"></label></div><div class="distribution-actions"><label><input v-model="filter.overdue_only" type="checkbox"> Overdue only</label><label><input v-model="filter.dormant" type="checkbox"> Dormant pool</label><button class="btn btn-g" :disabled="busy" @click="preview">Preview leads</button><button class="btn btn-gy" :disabled="!items.length" @click="exportPreview">Export preview</button></div>
</div><div v-if="items.length&&tab===0&&moveStep===2" class="tbl-wrap"><table><thead><tr><th>Select</th><th>Lead</th><th>Owner</th><th>Milestone</th><th>Last call</th><th>Next action</th></tr></thead><tbody><tr v-for="item in items" :key="item.lead"><td><input v-model="selected" type="checkbox" :value="item.lead" :aria-label="'Move '+item.lead"></td><td>{{item.lead}}</td><td>{{agents.find(a=>a.agent===item.owner)?.name||item.owner}}</td><td>{{item.milestone}}</td><td>{{item.last_call_result}}</td><td>{{item.next_action}} {{item.next_action_due}}</td></tr></tbody></table></div><button v-if="tab===0&&moveStep===2" class="btn btn-g" :disabled="!selected.length" @click="moveStep=3">Choose receiving agents →</button>
<div v-if="(tab===0&&moveStep===3)||tab===2||tab===3" class="distribution-fields"><label>Receiving agents<select v-model="toAgents" multiple><option v-for="a in agents" :key="a.agent" :value="a.agent">{{a.name}} · {{a.checked_in?'IN':'OUT'}} · {{a.open}} open</option></select></label><label>Distribution method<select v-model="method"><option v-for="(label,key) in methods" :key="key" :value="key">{{label}}</option></select></label></div>
<div v-if="tab===0&&moveStep===3" class="distribution-actions"><label><input v-model="clearFollowup" type="checkbox"> Clear existing follow-up time</label><label>Audit note<input v-model="note"></label><button class="btn btn-g" :disabled="busy||!selected.length||!toAgents.length||(overloaded.length&&!capacityAccepted)" @click="move">Move {{selected.length}} selected leads</button><button v-if="lastBatch" class="btn btn-gy" :disabled="busy" @click="undo">Undo last batch</button></div>
<div v-if="overloaded.length&&(tab===0||tab===3)" class="capacity-warning" role="alert"><strong>Workload limit exceeded</strong><p>{{overloaded.map(id=>agents.find(a=>a.agent===id)?.name||id).join(', ')}}. Check the workload before assigning more leads.</p><label><input v-model="capacityAccepted" type="checkbox"> I reviewed the workload and accept this assignment.</label></div><div v-if="tab===1"><button class="btn btn-gy" :disabled="busy" @click="checkScheduler">Check scheduler health</button><p v-if="schedulerStatus" role="status">Last execution: {{schedulerStatus.last_execution||'Not recorded'}} · {{schedulerStatus.paused?'Paused':schedulerStatus.stale?'Execution is overdue or unverified':'Running on schedule'}}<span v-if="schedulerStatus.legacy_active"> · Migration required to switch the legacy job to the updated native runner.</span></p><p>New rules start in test mode. Test runs record the proposed moves without changing ownership.</p><div class="tbl-wrap"><table><thead><tr><th>Rule</th><th>Type</th><th>Mode</th><th>Last run</th><th>Moved</th><th></th></tr></thead><tbody><tr v-for="r in distributionRules" :key="r.name"><td>{{r.rule_name}}</td><td>{{r.rule_type}}</td><td>{{r.enabled?(r.test_mode?'Test':'Live'):'Disabled'}}</td><td>{{r.last_run}}</td><td>{{r.last_moved||0}}</td><td><button class="btn btn-gy btn-sm" @click="editRule(r)">Edit</button><details><summary>Run details</summary><pre>{{r.last_preview||'No run recorded.'}}</pre></details></td></tr></tbody></table></div>
<form @submit.prevent="reviewRule"><div class="distribution-fields"><label>Rule name<input v-model="rule.rule_name" required></label><label>Type<select v-model="rule.rule_type"><option v-for="s in ruleTypes" :key="s">{{s}}</option></select></label><label>Wait<input v-model.number="rule.time_value" type="number" min="1" required></label><label>Unit<select v-model="rule.time_unit"><option>Minutes</option><option>Hours</option><option>Days</option></select></label><label>Maximum shuffles<input v-model.number="rule.max_shuffles" type="number" min="1"></label><label>Days<input v-model="rule.days" placeholder="Mon,Tue,Wed,Thu,Fri"></label><label>From<input v-model="rule.from_time" type="time"></label><label>To<input v-model="rule.to_time" type="time"></label><label>Every minutes<input v-model.number="rule.every_minutes" type="number" min="5"></label><label>Per-agent limit<input v-model.number="rule.per_agent_limit" type="number" min="1" max="500"></label><label>Absent mode<select v-model="rule.absent_mode"><option>Auto</option><option>Manual</option></select></label><label>Method<select v-model="rule.method"><option v-for="s in ['Lowest Load','Round Robin','Best Conversion','Most Bookings','Best Walk-ins','Free Hands Leads','Free Hands Follow-ups']" :key="s">{{s}}</option></select></label><label>From agents<select v-model="rule.from_agents" multiple><option v-for="a in agents" :key="a.agent" :value="a.agent">{{a.name}}</option></select></label><label>To agents<select v-model="rule.to_agents" multiple><option v-for="a in agents" :key="a.agent" :value="a.agent">{{a.name}}</option></select></label><label>Outcomes<select v-model="rule.statuses" multiple><option v-for="s in statuses" :key="s">{{s}}</option></select></label><label>Sources<select v-model="rule.sources" multiple><option v-for="s in bulkMeta.sources" :key="s">{{s}}</option></select></label></div><div class="distribution-actions"><label><input v-model="rule.enabled" type="checkbox" :true-value="1" :false-value="0"> Enabled</label><label><input v-model="rule.test_mode" type="checkbox" :true-value="1" :false-value="0"> Test mode</label><button class="btn btn-g" :disabled="busy">Review rule</button><button type="button" class="btn btn-gy" @click="rule=newRule();conflicts=[];force=''">New rule</button></div><div v-if="ruleReview" class="rule-applied"><h3>What is applied</h3><p>{{ruleReview.rule_name}} · {{ruleReview.rule_type}} · wait {{ruleReview.time_value}} {{ruleReview.time_unit}}</p><p>{{ruleReview.method}} · {{ruleReview.days}} · {{ruleReview.from_time}}–{{ruleReview.to_time}} · maximum {{ruleReview.max_shuffles}} shuffles</p><p>From: {{ruleReview.from_agents.join(', ')||'All eligible agents'}} → To: {{ruleReview.to_agents.join(', ')||'Eligible checked-in agents'}}</p><strong>{{ruleReview.test_mode?'TEST MODE · no leads will move':'LIVE MODE · eligible leads can move'}}</strong><button type="button" class="btn btn-g" :disabled="busy" @click="saveRule">Accept &amp; Apply</button></div><div v-if="conflicts.length" role="alert"><p>Overlapping rules: {{conflicts.map(c=>c.rule).join(', ')}}</p><label>Resolve overlap<select v-model="force"><option value="">Choose…</option><option value="replace">Disable overlapping rules</option><option value="keep">Keep both rules</option></select></label><button type="button" class="btn btn-g" :disabled="busy||!force" @click="saveRule">Accept overlap and apply</button></div></form></div>
<div v-if="tab===2"><button class="btn btn-g" :disabled="busy" @click="ranking">Calculate ranking</button><div class="tbl-wrap"><table><thead><tr><th>Agent</th><th>IN / OUT</th><th>Open</th><th>Overdue</th><th>Auto</th><th>Capacity</th></tr></thead><tbody><tr v-for="a in agents" :key="a.agent"><td>{{a.name}}</td><td>{{a.checked_in?'IN':'OUT'}}</td><td>{{a.open}}</td><td>{{a.overdue}}</td><td>{{a.auto&&!a.stopped?'On':'Stopped'}}</td><td>{{a.over_cap?'Over limit':'Available'}}</td></tr></tbody></table><table v-if="rank.length"><thead><tr><th>Rank</th><th>Agent</th><th>Conversion %</th><th>Show-up %</th><th>Score</th></tr></thead><tbody><tr v-for="a in rank" :key="a.agent"><td>{{a.rank}}</td><td>{{a.name}}</td><td>{{a.conv}}</td><td>{{a.showup}}</td><td>{{a.score}}</td></tr></tbody></table></div><form @submit.prevent="saveSettings"><h3>Workload settings</h3><div class="distribution-fields"><label v-for="(label,key) in {cap_overdue:'Overdue limit',cap_open:'Open lead limit',open_days:'Open lead window (days)',overdue_days:'Overdue window (days)',dormant_days:'Dormant after (days)'}" :key="key">{{label}}<input v-model.number="settings[key]" type="number" min="1" required></label></div><label>Senior closers<select v-model="settings.seniors" multiple><option v-for="a in agents" :key="a.agent" :value="a.agent">{{a.name}}</option><option v-for="id in (settings.seniors||[]).filter(id=>!agents.some(a=>a.agent===id))" :key="id" :value="id">{{id}}</option></select></label><label><input v-model="settings.cap_on" type="checkbox" :true-value="1" :false-value="0"> Apply capacity limits</label><button class="btn btn-g" :disabled="busy">Save settings</button></form></div>
<div v-if="tab===3"><p>Excel or CSV columns: name, mobile, source, branch. Optional: alt, city, interest, notes, agent. Up to 500 rows and 2 MB.</p><button class="btn btn-gy" @click="template">Download Excel template</button><label>Paste Excel or CSV rows<textarea v-model="pasteText" rows="5" placeholder="Include the header row"></textarea></label><button class="btn btn-gy" @click="readPaste">Read pasted rows</button><input type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" :disabled="busy" aria-label="Lead Excel or CSV" @change="fileChanged"><p>{{bulk.length}} rows ready for review.</p><label>Assignment<select v-model="bulkMode"><option value="auto">Automatic assignment</option><option value="agent">One agent</option><option value="split">Split across selected agents</option><option value="rank">Use ranking</option><option value="file">Agent column in file</option></select></label><label><input v-model="allowDup" type="checkbox"> Allow duplicate mobile numbers</label><button class="btn btn-g" :disabled="busy||!bulk.length" @click="preflight">Check every row</button><p v-if="checks">{{checks.ready}} ready · {{checks.invalid}} invalid · {{checks.skipped}} duplicates skipped</p><div v-if="checks" class="tbl-wrap"><table><thead><tr><th>Row</th><th>Name</th><th>Mobile</th><th>State</th><th>Validation</th></tr></thead><tbody><tr v-for="row in checks.rows" :key="row.row"><td>{{row.row}}</td><td>{{row.name}}</td><td>••••{{String(row.mobile||'').slice(-4)}}</td><td>{{row.state}}</td><td>{{row.errors.join(' ')}} {{row.duplicate?'Duplicate: '+row.duplicate:''}}</td></tr></tbody></table></div><div class="tbl-wrap"><table v-if="bulk.length&&!checks"><thead><tr><th>Name</th><th>Mobile</th><th>Source</th><th>Branch</th></tr></thead><tbody><tr v-for="r in bulk.slice(0,30)" :key="r.row"><td>{{r.name}}</td><td>••••{{r.mobile.slice(-4)}}</td><td>{{r.source}}</td><td>{{r.branch}}</td></tr></tbody></table></div><button class="btn btn-g" :disabled="busy||!checks||checks.invalid||!checks.ready||(overloaded.length&&!capacityAccepted)" @click="upload">Create {{bulk.length}} leads</button><div v-if="bulkResults" class="tbl-wrap"><table><thead><tr><th>Row</th><th>Result</th></tr></thead><tbody><tr v-for="r in bulkResults.results" :key="r.row"><td>{{r.row}}</td><td>{{r.ok?r.lead+' · '+r.owner:r.msg}}</td></tr></tbody></table></div></div>
<div v-if="tab===4"><p>Only Bhuvan and Naren can edit this permission list.</p><label>Allowed users, one login per line<textarea v-model="allowedUsers" rows="8" :disabled="!perm.can_edit_perm"></textarea></label><button v-if="perm.can_edit_perm" class="btn btn-g" :disabled="busy" @click="savePermissions">Save permissions</button></div>
</template></div></section>
</template>
<style scoped>.distribution-tabs,.distribution-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:14px 0}.distribution-tabs button[aria-pressed=true]{background:#16402d;color:white}.distribution-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:15px 0}.distribution-fields label,label:has(textarea){display:grid;gap:6px;font-size:12px}.distribution-fields input,.distribution-fields select,textarea{border:1px solid #d8cfb8;border-radius:7px;padding:8px;color:#214638;background:white;max-width:100%;box-sizing:border-box}select[multiple]{min-height:95px}textarea{width:100%;max-width:600px}pre{white-space:pre-wrap;max-width:450px;font-size:11px}.tbl-wrap{max-height:430px;overflow:auto}button{cursor:pointer}.distribution-steps{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.distribution-steps button[aria-current=step]{background:#16402d;color:white}.rule-applied{background:#e9f6ea;border:1px solid #438452;border-radius:10px;padding:14px;margin:14px 0}.capacity-warning{background:#fff2d9;border:1px solid #d7962c;border-radius:9px;padding:12px;margin:12px 0}</style>
